-- 初始化 是否震屏 屏幕移动
function M:initWuzhuangEvent()
    local pillarGridId = self.serverMapData.pillars_show
    if (not pillarGridId) or (pillarGridId <= 0) then
        return
    end
    TimeTools:delayTimeUnity(1,function()
        SceneManager:getCurSceneView().cameraController.Target = nil
        local cameraDoTween = self.camera:GetComponent("DOTweenAnimation")
        cameraDoTween:DORestart()
        TimeTools:delayTimeUnity(cameraDoTween.duration,function()
            self:sendEvent("show_no_move_messag", {hintText = Language:getTextByKey("qmdj_text_0004")}, "QiMenDunJia.QiMenDunJiaMain");
            local gridUnit = self.gridMgr:getGridUnitById(pillarGridId)
            self:setPassivityCameraTargetPos(gridUnit)
            self.serverMapData.pillars_show = -1
        end)
    end)
end

function M:loadFogMapData()
    -- 删除一遍战争迷雾数据
    if self.isFirstEnterQmdj then
        self.isFirstEnterQmdj = false
        -- 文件路径对应 FogOfWarEffect.cs 方法里SaveData()的 path
        --local delePath = CS.UnityEngine.Application.persistentDataPath.."/Saves/"..self.fogOfWarSavePath
        --CS.wt.framework.FileHelper.DeleteFile(delePath)
        local delePath = "/Saves/"..self.fogOfWarSavePath
        CS.wt.framework.LuaFileHelper.Inst:DeleteFile(delePath)
    end
    if not IsNull(CS.FogOfWarEffect.Instance) then
        CS.FogOfWarEffect.Instance:LoadData(self.fogOfWarSavePath)
        local walkGridIds = self.gridMgr.walkGridIds
        for _, gridUnit in pairs(self.gridMgr.gridUnitList) do
            if (walkGridIds[gridUnit.m_gridId] ~= nil) then
                self:refreshExplorer(gridUnit.position, self.fogOfWarRad);
            else
                if gridUnit.hideFogConfig and (gridUnit.hideFogConfig > 0) then
                    local curPos = gridUnit.position
                    local offsetPos = Vector3(curPos.x + self.fogOfWarOffset_X, curPos.y, curPos.z)
                    self:refreshExplorer(offsetPos, tonumber(gridUnit.hideFogConfig));
                end
            end
        end
    end
end

function M:refreshServerMapData(tempData)
    table.merge(self.serverMapData,tempData)
end

-- 设置被动型视野移动的目标点
function M:setPassivityCameraTargetPos(gridUnit)
    local targetGridUnit = self.gridMgr:getGridUnitById(gridUnit.m_monsterRefreshGridId)
    self.passivityCameraMovePos = targetGridUnit.position
    self.cameraMapTrans.position = gridUnit.position
    self:raycastEvent()
end

-- 被动型视野移动
function M:passivityCameraMove(dt)
    if not self.cameraMapTrans then
        return
    end
    local cameraMapFixPos = GlobalTools:ToFixVector3(self.cameraMapTrans.position)
    local cameraController = SceneManager:getCurSceneView().cameraController
    cameraController.Target = nil
    cameraController.CanDrag = false

    -- 起始点：self.cameraMapTrans.position
    -- 目标位置：self.passivityCameraMovePos
    local distance = Vector3.Distance(self.cameraMapTrans.position, self.passivityCameraMovePos);
    local dir = Vector3.Normalize(self.passivityCameraMovePos - self.cameraMapTrans.position)
    -- 3 是两个格子之间的 distance
    if distance > 3 then
        local speed = ConfigManager:getCommonValueById(664) or 100
        local configRefreshOffset = ConfigManager:getCommonValueById(665) or 50
        local offset = dir * 0.002 * tonumber(speed)
        offset.y = 0
        self.cameraMapTrans.position = self.cameraMapTrans.position + offset
        cameraController.transform.localPosition = cameraController.transform.localPosition + offset
        local dragEndPos = Vector3(CS.UnityEngine.Screen.width * 0.5, CS.UnityEngine.Screen.height * 0.5, 0)
        --Logger.logError("当前x的位置差是====="..math.abs(self.dragStartPos.x - dragEndPos.x) ..", y的位置差是="..math.abs(self.dragStartPos.y - dragEndPos.y).."，当前值是=="..self.dragRefreshOffset)
        if (math.abs(self.dragStartPos.x - dragEndPos.x) > configRefreshOffset) or (math.abs(self.dragStartPos.y - dragEndPos.y) > configRefreshOffset) then
            self.dragStartPos = dragEndPos
            self:raycastEvent()
            self:refreshPlayerImg()
        end
    else
        -- 设置两次，一次不够亮
        self:refreshExplorer(self.passivityCameraMovePos, self.fogOfWarRad );
        self:refreshExplorer(self.passivityCameraMovePos, self.fogOfWarRad );
        self.cameraMapTrans.position = self.passivityCameraMovePos
        -- 快到目标后，就不动了，也不赋值，赋值相相机会跳一下
        --cameraController.transform.localPosition = self.passivityCameraMovePos;
        self.passivityCameraMovePos = nil
        cameraController.CanDrag = true
        self:raycastEvent()
        self:refreshPlayerImg()
    end
end

-- 视野召回
function M:recoverViewByPlayerPos()
    if not self.player_view then
        return
    end
    self.isShowViewMainPlayerIcon = false
    self.gridMgr:refreshGridInfo(false, self.playerGridId)
    local playerTargetPos = self.player_view:get_position()
    SceneManager:getCurSceneView().cameraController.transform.position = playerTargetPos
    SceneManager:getCurSceneView().cameraController:ResetStart();
    local tranPos = self.player_view.tran
    SceneManager:getCurSceneView().cameraController.Target = tranPos
    self:sendEvent("show_playerImg_messag", {isShow = self.isShowViewMainPlayerIcon}, "QiMenDunJia.QiMenDunJiaMain");
end

