--重新设置场景数据
function M:resetSceneData( data )
    self.mouseDownTime = 0;
    if data ~= nil then
        self.qimendunjia_data = data;
    else
        self.qimendunjia_data = self.m_data;
    end
    
    GameMain.addUpdate("Qimendunjia_Update", handler(self,self.UnityUpdate))
    
    --初始化AStar
    self.aStar = require("Battle.Data.AStarSix").new();
    --6边型
    self.aStar:init("QiMenDunJiaSceneData", 1);
    --AStar寻路路径
    if self.path ~= nil then
        self.path:clear();
    else
        self.path = Battle.List.new()
    end
    -- 已经开启的格子 
    self.openCells = {}

    --创建奇门遁甲玩家 (先创建当前玩家，当前玩家脚下不创建其他玩家)
    self:createCurPlayer()
    self:refreshMemberPlayers(self.memberPlayersData)
    
    --临时移动完成
    self.temp_moveFinish_callback = nil;

    --向服务器发送的间隔时间
    self.sendToServerNow = true;
end

function M:stopScene()
    self.isMove = false;
    local cameraController = SceneManager:getCurSceneView().cameraController
    if cameraController then
        cameraController.CanDrag = (not self.isMove)
    end
    self.nextGrid = nil;
    self.path:clear();
    self.temp_target = nil
    self.isInMoving = false
    self:resetClickRoom();
    GameMain.removeUpdate("Qimendunjia_Update");
end

--销毁
function M:destroy( nextScene )
    -- 还原材质球
    if self.player_view and (not IsNull(self.player_view.obj)) then
        self:modiftPlayerMaterial(self.player_view.obj, true)
    end
    if self.restsPlayers then
        for _, itemData in pairs(self.restsPlayers) do
            if itemData.playerView and itemData.playerView.obj then
                self:modiftPlayerMaterial(itemData.playerView.obj, true)
            end
        end
    end
    self.restsPlayers = nil
    
    if not IsNull(CS.FogOfWarEffect.Instance) then
        CS.FogOfWarEffect.Instance:SaveData(self.fogOfWarSavePath)
    end
    if self.nameNodeList ~= nil then
        for _,v in pairs(self.nameNodeList) do
            U3DUtil:DestroyAndBundle(v, nil, nil, 0)
        end
    end
    if self.curPlayerName ~= nil then
        U3DUtil:DestroyAndBundle(self.curPlayerName, nil, nil, 0)
    end
    self.curPlayerName = nil
    if self.uiGiftBagNodeList ~= nil then
        for _,v in pairs(self.uiGiftBagNodeList) do
            U3DUtil:DestroyAndBundle(v, nil, nil, 0)
        end
    end
    self.uiGiftBagNodeList = nil
    if self.player_view.arrow ~= nil then
        U3DUtil:DestroyAndBundle(self.player_view.arrow, nil, nil, 0)
        self.player_view.arrow = nil;
    end
    if self.player_view.tanhao ~= nil then
        U3DUtil:DestroyAndBundle(self.player_view.tanhao, nil, nil, 0)
        self.player_view.tanhao = nil;
    end
    if self.player_view.shunyi ~= nil then
        U3DUtil:DestroyAndBundle(self.player_view.shunyi, nil, nil, 0)
        self.player_view.shunyi = nil;
    end
    if (not IsNull(self.sceneObj)) then
        U3DUtil:DestroyAndBundle(self.sceneObj, self.qmdj_sceneName, nil, 0)  
    end
    
    for _, itemData in pairs(self.showMonsterList) do
        if (not itemData.player_model) then
            U3DUtil:DestroyAndBundle(itemData.obj, nil, nil, 0)
        else
            if (not IsNull(itemData.obj)) and (self.bossPosList ~= nil) then
                local bodyTrans = itemData.obj.transform:Find("body")
                bodyTrans.localPosition = Vector3(self.bossPosList[1], self.bossPosList[2], self.bossPosList[3])
            end
        end
    end
    self.showMonsterList = nil
    for _, itemData in pairs(self.showGiftBagList) do
        U3DUtil:DestroyAndBundle(itemData.obj, nil, nil, 0)
    end
    self.showGiftBagList = nil
    for _, itemData in pairs(self.showSwordDeskList) do
        U3DUtil:DestroyAndBundle(itemData.obj, nil, nil, 0)
    end
    self.showSwordDeskList = nil
    for _, itemData in pairs(self.showForceStatuesList) do
        U3DUtil:DestroyAndBundle(itemData.obj, nil, nil, 0)
    end
    self.showForceStatuesList = nil
    for _, itemData in pairs(self.showLeagueList) do
        U3DUtil:DestroyAndBundle(itemData.obj, nil, nil, 0)
    end
    self.showLeagueList = nil
    for _, itemData in pairs(self.showShopList) do
        U3DUtil:DestroyAndBundle(itemData.obj, nil, nil, 0)
    end
    self.showShopList = nil
    for _, itemData in pairs(self.showWuzhuangList) do
        U3DUtil:DestroyAndBundle(itemData.obj, nil, nil, 0)
    end
    self.showWuzhuangList = nil
    for _, itemData in pairs(self.showPillarList) do
        U3DUtil:DestroyAndBundle(itemData.obj, nil, nil, 0)
    end
    self.showPillarList = nil

    U3DUtil:GameObjectDestroy(self.click_effect);
    self.click_effect = nil;
    self.openCells = {};
    
    self.gridMgr:destroy()
    self.gridMgr = nil
    
    GameMain.removeUpdate("Qimendunjia_Update");
    M.super.destroy(self,nextScene);
end

--场景加载完成
function M:closeloading()
