        EventDispatcher:registerTimeEvent("delay_close_loading_time",function()
            static_rootControl:updateMsg("close_sync_load_big_loading");
        end,0.1,0.1)
    end)
end

--通过中心格子获取周围格子
function M:getAroundGridUnit( center )
    local around = {}
    local around_index = ""
    if center.w_pos % 2 == 0 then
        --center 6-6        8-8
        --5-6
        if center.w_pos > 1 then
            local key = self.gridMgr:getGridIDByWidthAndHeight(center.w_pos - 1, center.h_pos)
            local map_data_item = self.gridMgr:getGridUnitById(key);
            if map_data_item ~= nil then
                table.insert(around, map_data_item);
                around_index = around_index.."-"..tostring(0);
            end
        end
        --7-6               9-8
        if center.w_pos < self.max_w then
            local key = self.gridMgr:getGridIDByWidthAndHeight(center.w_pos + 1, center.h_pos)
            local map_data_item = self.gridMgr:getGridUnitById(key);
            if map_data_item ~= nil then
                table.insert(around, map_data_item);
                around_index = around_index.."-"..tostring(2);
            end
        end
        --6-5               8-7
        if center.h_pos > 0 then
            local key = self.gridMgr:getGridIDByWidthAndHeight(center.w_pos, center.h_pos-1)
            local map_data_item = self.gridMgr:getGridUnitById(key);
            if map_data_item ~= nil then
                table.insert(around, map_data_item);
                around_index = around_index.."-"..tostring(4);
            end
        end
        --6-7               8-9
        if center.h_pos < self.max_h then
            local key = self.gridMgr:getGridIDByWidthAndHeight(center.w_pos, center.h_pos + 1)
            local map_data_item = self.gridMgr:getGridUnitById(key);
            if map_data_item ~= nil then
                table.insert(around, map_data_item);
                around_index = around_index.."-"..tostring(1);
            end
        end
        --7-5               9-7
        if center.w_pos < self.max_w and center.h_pos > 0 then
            local key = self.gridMgr:getGridIDByWidthAndHeight(center.w_pos + 1, center.h_pos - 1)
            local map_data_item = self.gridMgr:getGridUnitById(key);
            if map_data_item ~= nil then
                table.insert(around, map_data_item);
                around_index = around_index.."-"..tostring(3);
            end
        end
        --5-5               7-7
        if center.h_pos > 0 and center.w_pos > 0 then
            local key = self.gridMgr:getGridIDByWidthAndHeight(center.w_pos - 1, center.h_pos - 1)
            if center.w_pos < self.max_w then
                local map_data_item = self.gridMgr:getGridUnitById(key);
                if map_data_item ~= nil then
                    table.insert(around, map_data_item);
                    around_index = around_index.."-"..tostring(5);
                end
            end
        end
    else
        --center 5-5
        --4-5
        if center.w_pos > 0 then
            local key = self.gridMgr:getGridIDByWidthAndHeight(center.w_pos - 1, center.h_pos)
            local map_data_item = self.gridMgr:getGridUnitById(key);
            if map_data_item ~= nil then
                table.insert(around, map_data_item);
                around_index = around_index.."-"..tostring(5);
            end
        end
        --6-5
        if center.w_pos < self.max_w then
            local key = self.gridMgr:getGridIDByWidthAndHeight(center.w_pos + 1, center.h_pos)
            local map_data_item = self.gridMgr:getGridUnitById(key);
            if map_data_item ~= nil then
                table.insert(around, map_data_item);
                around_index = around_index.."-"..tostring(3);
            end
        end
        --5-4
        if center.h_pos > 0 then
            local key = self.gridMgr:getGridIDByWidthAndHeight(center.w_pos, center.h_pos-1)
            local map_data_item = self.gridMgr:getGridUnitById(key);
            if map_data_item ~= nil then
                table.insert(around, map_data_item);
                around_index = around_index.."-"..tostring(4);
            end
        end
        --5-6
        if center.h_pos < self.max_h then
            local key = self.gridMgr:getGridIDByWidthAndHeight(center.w_pos, center.h_pos + 1)
            local map_data_item = self.gridMgr:getGridUnitById(key);
            if map_data_item ~= nil then
                table.insert(around, map_data_item);
                around_index = around_index.."-"..tostring(1);
            end
        end

        --4-6
        if center.w_pos > 0 and center.h_pos < self.max_h then
            local key = self.gridMgr:getGridIDByWidthAndHeight(center.w_pos - 1, center.h_pos + 1)
            local map_data_item = self.gridMgr:getGridUnitById(key);
            if map_data_item ~= nil then
                table.insert(around, map_data_item);
                around_index = around_index.."-"..tostring(0);
            end
        end
        --6-6
        if center.h_pos < self.max_h and center.w_pos < self.max_w then
            local key = self.gridMgr:getGridIDByWidthAndHeight(center.w_pos + 1, center.h_pos + 1)
            if center.w_pos < self.max_w then
                local map_data_item = self.gridMgr:getGridUnitById(key);
                if map_data_item ~= nil then
                    table.insert(around, map_data_item);
                    around_index = around_index.."-"..tostring(2);
                end
            end
        end
    end
    return around, around_index;
end


--更新玩家移动位置
function M:updatePlayerMove( dt )
    local targetGrid = self.targetGrid
    if self.isMove == true then
        if self.nextGrid ~= nil then
            local pos = self.nextGrid.position
            local grid_fix_pos = GlobalTools:ToFixVector3(pos);
            local dir = GlobalTools:Dir(grid_fix_pos,self.player.position);
            local distance = GlobalTools:Distance(self.player.position, grid_fix_pos);
            --Logger.logError("当前玩家的位置是(".. self.player.position.x .. ", ".. self.player.position.y .. ", ".. self.player.position.z ..")"..",, 目标点位置是 = ("..grid_fix_pos.x..", "..grid_fix_pos.y..", "..grid_fix_pos.z..")")
            self.player:setForward(dir)
            --Logger.logError("当前的距离值是==="..distance.. ", 目标的距离值是=="..GlobalTools:ToFix2(GlobalTools.base0_2))
            if distance > GlobalTools:ToFix2(GlobalTools.base0_2) then
                local dt_fix = GlobalTools:CommonToFix(dt);
                local time = GlobalTools:Mul(dt_fix, GlobalTools.base2)
                self.player:move_no_coillder(dir, time);
            else
                self.nextGrid = nil;
            end
        end

        if self.nextGrid == nil then
            ---移动
            if self.path.Count > 0 then
                -- 大于7个格子要瞬移          
                if self.path.Count >= 7 then
                    for i = 1, self.path.Count do
                        local point = self.path:get(i-1);
                        self.movePassPath:add(point);
                    end
                    self.nextGrid = self.path:get(self.path.Count - 1);
                    self.startGrid = self.nextGrid
                    local key = self.gridMgr:getGridIDByWidthAndHeight(self.nextGrid.index_pos.x, self.nextGrid.index_pos.y)
                    self.path:clear();
                    local pos = self.nextGrid.position
                    local grid_fix_pos = GlobalTools:ToFixVector3(pos);
                    grid_fix_pos.y = self.player.position.y;
                    self.player:setPos(grid_fix_pos)
                    if _G.next(self.summon_list) then
                        for i, v in ipairs(self.summon_list) do
                            v:setPos(grid_fix_pos - FixVector3.New(1,0,1) * GlobalTools.base2_5)
                        end
                    end
                    if self.player_view and self.player_view.shunyi ~= nil then
                        self.player_view.shunyi:SetActive(false);
                        self.player_view.shunyi:SetActive(true);
                    end   
                    
                    -- 瞬移添加迷雾
                    self:setObjFogOfWarByPlayerPos()
                    -- 瞬移后刷新格子
                    --self:moveEndEvent(self.nextGrid.m_gridId)
                else
                    --下一个格子
                    self.nextGrid = self.path:get(0);
                    --起始格子 
                    self.startGrid = self.nextGrid
                    --路径中移除
                    self.path:removeAt(0);
                    --移动路径
                    self.movePassPath:add(self.nextGrid);
                    -- 显示当前格子站的人
                end
            else
                self.targetGrid = nil;
                self.isMove = false;
                local cameraController = SceneManager:getCurSceneView().cameraController
                if cameraController then
                    cameraController.CanDrag = (not self.isMove)
                end
                self.sendToServerNow = true;
                self.player.animator:changeState("idle")
                --移动结束之后
                if self.gotoFinish ~= nil then
                    self.gotoFinish()
                    self.gotoFinish = nil;
                else
                    --只有点击空白的格子才能用这个延迟时间
                    self.curMoveEndTime = self.moveEndSendToServer;
                end
                --static_rootControl:updateMsg("guide_check",data,"MazeStage")
            end
        end
    else
        --临时目标
        --if self.temp_target ~= nil then
        --    self.isInMoving = true;
        --    local pos = self.nextGrid.position
        --    local grid_fix_pos = GlobalTools:ToFixVector3(pos);
        --    local dir = GlobalTools:Dir(grid_fix_pos,self.player.position);
        --    local distance = GlobalTools:Distance(self.player.position, grid_fix_pos);
        --    self.player:setForward(dir)
        --    if distance > GlobalTools:ToFix2(GlobalTools.base0_3) then
        --        local dt_fix = GlobalTools:CommonToFix(dt);
        --        local time = GlobalTools:Mul(dt_fix, GlobalTools.base5)
        --        self.player:move_no_coillder(dir, time);
        --    else
        --        self.isInMoving = false;
        --        self.player.animator:changeState("idle")
        --        self.sendToServerNow = true;
        --        local key = self.gridMgr:getGridIDByWidthAndHeight(self.temp_target.index_pos.x, self.temp_target.index_pos.y)
        --        local center_cell_data = self.gridMgr:getGridUnitById(key)
        --        --self:sendEvent("maze_move_grid", center_cell_data, "MazeStage");              ------------------------------------------- 发送刷新
        --        --if self.temp_target.value == 0 then
        --        --    self:refreshCells(center_cell_data, false, true);
        --        --end
        --        --self:checkBoxAround(center_cell_data);
        --        --self:moveTempFinish()
        --        self.temp_target = nil;
        --    end
        --end
    end

    if self.curMoveEndTime > 0 then
        self.curMoveEndTime = self.curMoveEndTime - dt;
        if self.curMoveEndTime <= 0 then
            --goto完之后可以继续点击
            if self.temp_target == nil then
                self:resetClickRoom();
            end
            self:sendToServer(targetGrid)    
        end
    end
end

-- 创建其他玩家
function M:refreshMemberPlayers(members)
    if not members then
        return
    end
    if table.nums(members) <= 0 then
        return
    end
    self.memberPlayersData = members
    if self.restsPlayers == nil then
        self.restsPlayers = {}
        for strGridId, itemData in pairs(self.memberPlayersData) do
            local gridId = tonumber(strGridId)
            -- 当前玩家位置不出人，宝箱位置不出人
            local gridUnit = self.gridMgr:getGridUnitById(gridId)
            if gridUnit and (gridId ~= self.playerGridId) and (gridUnit.m_gridType ~= GlobalConfig.GridType.GiftBag) then
                self:createOneMemberPlayer(gridId, itemData)
            end
        end
    else
        local tempGrids = {}
        for strGridId, itemData in pairs(self.memberPlayersData) do
            local gridId = tonumber(strGridId)
            -- 当前玩家位置不出人，宝箱位置不出人
            local gridUnit = self.gridMgr:getGridUnitById(gridId)
            if (gridId ~= self.playerGridId) and (gridUnit.m_gridType ~= GlobalConfig.GridType.GiftBag) then
                local playerItemData = itemData[1]
                if playerItemData then
                    local playerId = playerItemData.uid
                    tempGrids[playerId] = playerId
                    if self.restsPlayers[playerId] == nil then
                        self:createOneMemberPlayer(gridId, itemData)
                    else
                        self:modifyOneMemberPlayer(playerId, gridId)
                    end
                end
            end
        end
        for playerId, playerInfo in pairs(self.restsPlayers) do
            if not tempGrids[playerId] then
                self:deleteOneMemberPlayer(playerId, playerInfo)
            end
        end
    end
end

-- ui单个成员名字称号
-- sendType, 1添加，2删除, 3隐藏， 4显示
function M:sendUIMemberPlayerName(playerId, sendType)
    if sendType == 1 then
        self:createMemberPlayerInfo(playerId)
    elseif sendType == 2 then
        self:deleteMemberPlayerInfo(playerId)
    elseif sendType == 3 then
        self:modifyMemberPlayerInfo(playerId, false)
    elseif sendType == 4 then
        self:modifyMemberPlayerInfo(playerId, true)
    end
end

