-- 删除成员头顶信息条
function M:deleteMemberPlayerInfo(playerId)
    if (self.nameNodeList ~= nil) and (self.nameNodeList[playerId] ~= nil) then
        U3DUtil:DestroyAndBundle(self.nameNodeList[playerId], nil,nil,0)
        self.nameNodeList[playerId] = nil
    end
