-- 创建成员头顶信息条
function M:createMemberPlayerInfo(playerId, isCurPlayer)
    if IsNull(self.Canvas) ~= false then
        return
    end
    -- sendType, 1添加，2修改，3删除
    -- gridPos
    -- playerData
    local nameNode = UIUtil.findTrans(self.Canvas.transform, "mapMemberNameBarNode")
    if isCurPlayer then
        if self.player_view and (not IsNull(self.player_view.head)) then
            local name = UserDataManager.user_data:getUserStatusDataByKey("name") or ""
            local title = UserDataManager.user_data:getUserStatusDataByKey("title") or nil
            self.curPlayerName = self:createMemberNameBar(name,title, self.player_view.head, nameNode)
        end
    else
        if self.restsPlayers and self.restsPlayers[playerId] then
            local playerInfo = self.restsPlayers[playerId]
            local playerItemData = playerInfo.playerItemData
            self.nameNodeList[playerId] = self:createMemberNameBar(playerItemData.name, playerItemData.title, playerInfo.playerView.head, nameNode)
        end
    end
end

