-- 创建宝箱头顶信息条
function M:createGiftBagBarInfo(gridId)
    if IsNull(self.Canvas) ~= false then
        return
    end
    local gridUnit = self.gridMgr:getGridUnitById(gridId)
    if not gridUnit then
        return
    end
    if (gridUnit.m_gridType ~= GlobalConfig.GridType.GiftBag) or (gridUnit.specialId <= 0) then
        return
    end
    local gve_massifData = ConfigManager:getCfgByName("gve_massif")
    local giftBagXlsxData = gve_massifData[gridUnit.specialId] 
    local giftInfo = giftBagXlsxData.box_reward[1]
    local nameNode = UIUtil.findTrans(self.Canvas.transform, "mapgiftBagBarNode")
    self.uiGiftBagNodeList[gridId] = self:createGiftBagBar(gridId, giftInfo, nameNode)
end
function M:createGiftBagBar(gridId, giftInfo, parent)
    if self.showGiftBagList[gridId] == nil then
        return nil
    end
    local giftBagObj = self.showGiftBagList[gridId]
    if IsNull(giftBagObj.obj) then
        return nil
    end
    local giftBagHand = giftBagObj.obj.transform:Find("head")
    if IsNull(giftBagHand) then
        return
    end
    local giftBagNodeBar = ResourceUtil:GetUIItem("QiMenDunJia/sceneObject/Qmdj_giftBagInfoNode", parent.gameObject, "ui_prefabs")
    local data = RewardUtil:getProcessRewardData(giftInfo)
    local luaBehaviour = giftBagNodeBar:GetComponent("LuaBehaviour")
    LuaBehaviourUtil.setImg(luaBehaviour, "img_icon", data.icon_name, data.atlas_name or "item_icon")
    
    local quality_item  -- = nil
    local frame_name    -- = nil
    if data.data_type == RewardUtil.REWARD_TYPE_KEYS.HEROS or data.data_type == RewardUtil.REWARD_TYPE_KEYS.HEROSEXT or data.data_type == RewardUtil.REWARD_TYPE_KEYS.HEROS_EXT then
        quality_item = GlobalConfig.HERO_QUALITY_COMMON_SETTING[data.quality] or GlobalConfig.HERO_QUALITY_COMMON_SETTING[1]
        frame_name = quality_item.hero_item_frame
        LuaBehaviourUtil.setImg(luaBehaviour, "img_gridBagBg", frame_name, "hero_head_ui")
    elseif data.data_type == RewardUtil.REWARD_TYPE_KEYS.MYSTIC then
        quality_item = GlobalConfig.QUALITY_COMMON_SETTING[data.quality] or GlobalConfig.QUALITY_COMMON_SETTING[1]
        frame_name = quality_item.mystic_frame_name
        LuaBehaviourUtil.setImg(luaBehaviour, "img_gridBagBg", frame_name, "equip_icon")
    else
        quality_item = GlobalConfig.QUALITY_COMMON_SETTING[data.quality] or GlobalConfig.QUALITY_COMMON_SETTING[1]
        frame_name = quality_item.frame_name
        LuaBehaviourUtil.setImg(luaBehaviour, "img_gridBagBg", frame_name, "equip_icon")
    end
    LuaBehaviourUtil.setText(luaBehaviour, "text_count", GameUtil:formatValueToString(data.data_num))
    local WorldPointUI = giftBagNodeBar:GetComponent("WorldPointUI")

    -- 购买按钮
    local btn_buyBtn = luaBehaviour:FindGameObject("img_icon")
    UIUtil.setButtonClick(
            btn_buyBtn.transform,
            function()
                if data.data_type == RewardUtil.REWARD_TYPE_KEYS.EQUIPS then
                    static_rootControl:closeView("HeroInfo.EquipmentPop",nil, false)
                    if data.oid then
                        static_rootControl:openView("HeroInfo.EquipmentPop", {equip_id = data.oid})
                    else
                        static_rootControl:openView("HeroInfo.EquipmentPop", {equip_cfg_id = data.data_id, race = data.race, look_model = 3})
                    end
                elseif data.data_type == RewardUtil.REWARD_TYPE_KEYS.EQUIP_AFFIX then
                    static_rootControl:openView("HeroInfo.EquipmentPop", {equip_cfg = data, look_model = 3, affix = true})
                elseif data.data_type == RewardUtil.REWARD_TYPE_KEYS.ITEM then
                    local tempCfg = data.item_cfg
                    if tempCfg and (tempCfg.sort == 1) and (tempCfg.type == 1) then
                        --- 阵营白色武器随机箱奖励特殊处理
                        local random_chest = ConfigManager:getCfgByName("random_chest") or {}
                        local tempEftData = tempCfg.effect[1]
                        local random_chest_item = random_chest[tempEftData[2]]
                        if random_chest_item then
                            local sort = random_chest_item.sort
                            local configs = random_chest_item.configs or {}
                            if sort == 2 then -- 赛季展示
                                local index, season = GameUtil:getCurSeasonRewardIndex(configs)
                                if configs[index] and configs[index].rewards then
                                    tempCfg.content_show = configs[index].rewards
                                end
                            end
                        end
                    end
                    static_rootControl:closeView("Item.ItemDetail",nil, false)
                    static_rootControl:openView("Item.ItemDetail", {show_data = data, display = true})
                elseif data.data_type == RewardUtil.REWARD_TYPE_KEYS.HEROS or data.data_type == RewardUtil.REWARD_TYPE_KEYS.HEROSEXT or data.data_type == RewardUtil.REWARD_TYPE_KEYS.HEROS_EXT then
                    static_rootControl:closeView("Pops.HeroLookInfo",nil, false)
                    static_rootControl:openView("Pops.HeroLookInfo", {hero_id = data.data_id, is_new = false})
                elseif data.data_type == RewardUtil.REWARD_TYPE_KEYS.HERO_SKIN then
                    --local hero_id = data.item_cfg.hero
                    static_rootControl:closeView("Pops.HeroSkinLookInfo",nil, false)
                    static_rootControl:openView("Pops.HeroSkinLookInfo", {is_new = false, skin_id = data.data_id})
                elseif data.data_type == RewardUtil.REWARD_TYPE_KEYS.MYSTIC then
                    static_rootControl:closeView("SutraDepository.DepositoryPop",nil, false)
                    static_rootControl:openView("SutraDepository.DepositoryPop", {oid = data.data_id, mode = 2})
                elseif data.data_type == RewardUtil.REWARD_TYPE_KEYS.TITLE then
                    static_rootControl:closeView("Title.TitleDetailp",nil, false)
                    static_rootControl:openView("Title.TitleDetail", {show_data = data, display = true})
                --else
                    --static_rootControl:closeView("Pops.CommonItemTipsPop",nil, false)
                    --static_rootControl:openView("Pops.CommonItemTipsPop", {data = data, target_obj = infoNode})
                end
            end
    )
    
    WorldPointUI.target = giftBagHand   --.gameObject
    return giftBagNodeBar
end

function M:createMemberNameBar(name, title, head, parent)
    local nameNodeBar = ResourceUtil:GetUIItem("QiMenDunJia/sceneObject/Qmdj_playerNameNode", parent.gameObject, "ui_prefabs")
    local luaBehaviour = nameNodeBar:GetComponent("LuaBehaviour")
    LuaBehaviourUtil.setTextByLanKey(luaBehaviour, "text_nameText", name)
    local title_id = title
    if title_id and title_id ~= 0 then
        LuaBehaviourUtil.setObjectVisible(luaBehaviour, "head_title_img", true)
        local title_obj = luaBehaviour:FindGameObject("head_title_img")
        local name_img = luaBehaviour:FindImage("head_title_img")
        local cfg = UserDataManager.title_data:getTitleConfigById(title_id)
        if cfg and name_img and title_obj then
            name_img.enabled = true
            GameUtil:setTextureLoadTitleLanImgText(name_img, cfg.icon) -- 设置称号图片
            name_img:SetNativeSize()
            UIUtil.setScale(title_obj.transform, 0.7)
        end
        UIUtil.destroyAllChild(name_img.gameObject.transform)
        if cfg.title_effect and cfg.title_effect ~= "" then
            name_img.enabled = false
            ResourceUtil:GetUIEffectItem("Headtitle/" .. cfg.title_effect, name_img.gameObject)
        end
    else
        LuaBehaviourUtil.setObjectVisible(luaBehaviour, "head_title_img", false)
    end
    local WorldPointUI = nameNodeBar:GetComponent("WorldPointUI")
    WorldPointUI.target = head
    return nameNodeBar
end

-- 设置成员玩家状态（显示隐藏）
function M:setOneMemberPlayerByGridId(playerId, isShow)
    if self.restsPlayers[playerId] ~= nil then
        local playerInfo = self.restsPlayers[playerId]
        if  playerInfo.playerView and  playerInfo.playerView.model then
            playerInfo.playerView.model:hideBody(isShow)
        end
    end
end

-- 修改一个成员玩家位置
function M:modifyOneMemberPlayer(playerId, gridId)
    local playerInfo = self.restsPlayers[playerId]
    local oldGridUnit = self.gridMgr:getGridUnitById(playerInfo.gridId)
    oldGridUnit:setExistPlayerUid(-1)
    local gridUnit = self.gridMgr:getGridUnitById(gridId)
    gridUnit:setExistPlayerUid(playerId)
    self:setPlayerPosAndAni(gridUnit, playerInfo.playerObj)
end

-- 删除一个成员玩家
function M:deleteOneMemberPlayer(playerId, playerInfo)
    local gridUnit = self.gridMgr:getGridUnitById(playerInfo.gridId)
    gridUnit:setExistPlayerUid(-1)
    self:sendUIMemberPlayerName(playerInfo.playerItemData.uid, 2)
    if playerInfo.playerView and (not IsNull(playerInfo.playerView.obj)) then
        self:modiftPlayerMaterial(playerInfo.playerView.obj, true)
    end
    self.plyMgr:destoryPlayer(playerInfo.playerView.model, false)
    self.restsPlayers[playerId] = nil
end

function M:getUserOwnAvatar(avatar_id)
    local cfg = ConfigManager:getPlayerPictureCfg(avatar_id)
    if cfg then
        if cfg.unlock == 1 then -- 获得卡牌解锁
            return avatar_id
        elseif cfg.unlock == 2 then -- 运营活动解锁,可能卡牌表中没有，用104的卡牌改变模型
            return 104, cfg.prefab
        elseif cfg.unlock == 3 then -- 获得皮肤解锁,可能卡牌表中没有，用104的卡牌改变模型
            local skin = ConfigManager:getHeroSkinCfg(avatar_id)
            return 104, skin.prefab
        end
    end
    return 104
end

-- 创建一个成员玩家
function M:createOneMemberPlayer(gridId, itemData)
    local playerItemData = itemData[1]
    if playerItemData then
        local playerId = playerItemData.uid
        local tempAvatar = checknumber(playerItemData.avatar)
        local avatar ,custom_prefab  = self:getUserOwnAvatar(tempAvatar)
        local playerData = { id = checknumber(avatar), evo = 0, custom_prefab = custom_prefab }
        --玩家脚下的当前格子
        local gridUnit = self.gridMgr:getGridUnitById(gridId)
        gridUnit:setExistPlayerUid(playerId)
        local playerObj = self.plyMgr:createPlayer(playerData,1,0,nil,nil)
        playerObj.loadPlayerViewFinish = function(ply)
            self:setPlayerPosAndAni(gridUnit, playerObj, ply)
            self.plyMgr:playerSpawnCamp(1);
            self.restsPlayers[playerId] = {
                playerObj = playerObj,
                playerView = ply,
                gridId = gridId,
                playerItemData = playerItemData,
            }
            self:sendUIMemberPlayerName(playerId, 1)
            -- 删除英雄召唤物
            if playerObj and playerObj.summonMgr then
                playerObj.summonMgr:clear()
            end
            -- 修改材质
            self:modiftPlayerMaterial(ply.obj, false)
        end
    end
end

-- 设置玩家位置 动作 迷雾 放大
function M:setPlayerPosAndAni(gridUnit, playerObj, playerView)
    local pos = Vector3(gridUnit.m_posX, gridUnit.m_posY,gridUnit.m_posZ);
    pos.y = 0;
    local fix_pos = FixVector3.New(0,0,0);
    fix_pos.x = GlobalTools:CommonToFix( pos.x );
    fix_pos.y = GlobalTools:CommonToFix( pos.y );
    fix_pos.z = GlobalTools:CommonToFix( pos.z );
    --放大
    local scaleConfig = ConfigManager:getCommonValueById(638) or 1
    playerObj:setBaseScale(GlobalTools:CommonToFix(tonumber(scaleConfig)))
    -- 阴影
    if (not IsNull(playerView.luaViewHelper)) then
        playerView.luaViewHelper:Spawn()
    end
    -- 添加迷雾可视
    self:setObjFogOfWar(playerView.obj, pos, self.fogOfWarRad)
    --玩家设定位置
    playerObj:setPos( fix_pos )
    if playerObj.animator ~= nil then
        playerObj.animator:changeState("idle")
    end
end

-- 对模型添加迷雾可视
function M:setObjFogOfWar(playerObj, pos, radius)
    local fogPlayer = playerObj:AddComponent(typeof(CS.FogOfWarExplorer))
    fogPlayer.radius = self.fogOfWarRad;
    self:refreshExplorer(pos, radius)
end

function M:refreshExplorer(pos, radius)
    if not IsNull(CS.FogOfWarEffect.Instance) then
        CS.FogOfWarEffect.Instance:RefreshExplorer(pos, radius);
    end
end

-- 设置迷雾显示，(玩家传送使用)
function M:setObjFogOfWarByPlayerPos()
    if not self.player_view then
        return
    end
    if IsNull(self.player_view.obj) then
        return
    end
    local curGridId = self.playerGridId
    local gridUnit = self.gridMgr:getGridUnitById(curGridId)
    self:setObjFogOfWar(self.player_view.obj, gridUnit.position, self.fogOfWarRad)
end

--创建当前玩家
function M:createCurPlayer()
    if self.player == nil then
        local avatar,custom_prefab = GameUtil:getUserOwnAvatar()
        local playerData = { id = tonumber(avatar), evo = 0, custom_prefab = custom_prefab }
        --玩家脚下的当前格子
        local cell_data = self.gridMgr:getGridUnitById(self.playerGridId);
        --起始格子
        self.startGrid = self.aStar.sceneData.data[cell_data.w_pos][cell_data.h_pos];      
        --Logger.log(" 起始格子 "..self.startGrid.index_pos.x.." , "..self.startGrid.index_pos.y )
        --昆仑需要创建宠物
        self.player = self.plyMgr:createPlayer(playerData,1,0,nil,nil)
        self.player.loadPlayerViewFinish = function(ply)
            self.player_view = ply;
            if (not IsNull(self.player_view.luaViewHelper)) then
                self.player_view.luaViewHelper:Spawn()
                self:modiftPlayerMaterial(self.player_view.obj, false)
            end
            local pos = Vector3(cell_data.m_posX, 0,cell_data.m_posZ);
            local fix_pos = FixVector3.New(0,0,0);
            fix_pos.x = GlobalTools:CommonToFix( pos.x );
            fix_pos.y = GlobalTools:CommonToFix( pos.y );
            fix_pos.z = GlobalTools:CommonToFix( pos.z );
            --玩家设定位置
            self.player:setPos( fix_pos )
            self.plyMgr:playerSpawnCamp(1);
            if self.player.animator ~= nil then
                self.player.animator:changeState("idle")
            end
            -- 添加迷雾可视
            self:setObjFogOfWar(self.player_view.obj, pos, self.fogOfWarRad)
            local playerTargetPos = self.player_view:get_position()
            SceneManager:getCurSceneView().cameraController.transform.position = playerTargetPos
            SceneManager:getCurSceneView().cameraController:ResetStart();
            local tranPos = self.player_view.tran
            SceneManager:getCurSceneView().cameraController.Target = tranPos
            self:closeloading();
            --放大
            local scaleConfig = ConfigManager:getCommonValueById(638) or 1
            self.player:setBaseScale(GlobalTools:CommonToFix(tonumber(scaleConfig))) 
            --场景状态改成3
            self:set_sceneState(3)
            --self:setViewEffect();
            if self.mainPlayerloadFinish ~= nil then
                self.mainPlayerloadFinish()
            end
            self.gridMgr:refreshGridInfo( false, self.playerGridId )
            --Logger.logError("refreshGridInfo=============11111111111111=========="..self.playerGridId)
            self:createMemberPlayerInfo(nil, true)
            
            self.summon_list_view, self.summon_list = GlobalTools:CreateSummon(self.player, GlobalTools.base3, GlobalTools.base12)
            if _G.next(self.summon_list) then
                for i, v in ipairs(self.summon_list) do
                    v:setPos(fix_pos - FixVector3.New(1,0,1) * GlobalTools.base2_5)
                end
            end
        end
    else
        local cell_data = self.gridMgr:getGridUnitById(self.playerGridId);
        self.startGrid = self.aStar.sceneData.data[cell_data.w_pos][cell_data.h_pos];  
        local pos = Vector3(cell_data.m_posX, cell_data.m_posY,cell_data.m_posZ);
        pos.y = 0;
        local fix_pos = FixVector3.New(0,0,0);
        fix_pos.x = GlobalTools:CommonToFix( pos.x );
        fix_pos.y = GlobalTools:CommonToFix( pos.y );
        fix_pos.z = GlobalTools:CommonToFix( pos.z );
        --玩家设定位置
        self.player:setPos( fix_pos )             
        self.plyMgr:playerSpawnCamp(1);
        if self.player_view and self.player_view.tran then
            SceneManager:getCurSceneView().cameraController.transform.position = self.player_view:get_position()
            SceneManager:getCurSceneView().cameraController:ResetStart();
            SceneManager:getCurSceneView().cameraController.Target = self.player_view.tran
        end
        self:closeloading();
        --放大
        local scaleConfig = ConfigManager:getCommonValueById(638) or 1
        self.player:setBaseScale(GlobalTools:CommonToFix(tonumber(scaleConfig)))
        self:set_sceneState(3)
        self.player.animator:changeState("idle")
        self.gridMgr:refreshGridInfo(false, self.playerGridId)
        --Logger.logError("refreshGridInfo=============4444444444444=========="..self.playerGridId)
        --self:checkBoxAround( cell_data );
        if self.summon_list ~= nil and _G.next(self.summon_list) then
            for i, v in ipairs(self.summon_list) do
                v:setPos(fix_pos - FixVector3.New(1,0,1) * GlobalTools.base2_5)
            end
        end
    end
end

-- 修改
function M:modiftPlayerMaterial(playerObj, isRestore)
    if IsNull(playerObj) then
        return
    end
    local body = playerObj.transform:Find("body")
    if IsNull(body) then
        return
    end
    local cinfigIndex = isRestore and 1 or 2
    local materialConfig = RoleShadowValues[cinfigIndex]
    local renderers = body:GetComponentsInChildren(typeof(CS.UnityEngine.SkinnedMeshRenderer), true)
    for i = 1, renderers.Length do
        local itemMat = renderers[i -1]
        local mats = itemMat.materials
        if mats.Length > 0 then
            local curMater = mats[0]
            curMater:SetVector("_ShadowDir",Vector4(materialConfig.shadowX, materialConfig.shadowY, materialConfig.shadowZ, materialConfig.shadowW))
            curMater:SetFloat("_ShadowFalloff", materialConfig.fallOff)
        end
    end
end

