-- 刷新地上物通用方法
function M:refreshGroundObject(tempDatas, showGroundList, groupTrans)
    -- 将不在可视范围内移除
    local tempShowGroundList = table.nums(showGroundList)
    if tempShowGroundList > 0 then
        for gridId, itemData in pairs(showGroundList) do
            if tempDatas[itemData.gridId] == nil then
                if not itemData.player_model then
                    local gridUnit = self.gridMgr:getGridUnitById(gridId)
                    if gridUnit.m_gridType == GlobalConfig.GridType.GiftBag then
                        self:deleteGiftBagBarInfo(gridId)
                    end
                    -- 不在新的可视范围, 移出
                    U3DUtil:DestroyAndBundle(itemData.obj, nil, nil, 0)
                    showGroundList[gridId] = nil
                end
            end
        end
    end
    -- 没有则return
    if table.nums(tempDatas) <= 0 then
        return
    end
    -- 添加可视范围内
    local gve_massifData = ConfigManager:getCfgByName("gve_massif")
    for gridId, _ in pairs(tempDatas) do
        if showGroundList[gridId] == nil then
            local gridUnit = self.gridMgr:getGridUnitById(gridId)
            --TODO 特殊处理了八卦阵，含有八卦阵数据的怪物类型, 脚下显示八卦阵
            self:specialWuZhuang(gridUnit, gve_massifData, self.houseGroupTrans, self.showWuzhuangList)
            local specialId = gridUnit.specialId
            if specialId > 0 then
                local xlsxData = gve_massifData[specialId]
                self:createObj(xlsxData, groupTrans, gridUnit, showGroundList )
            end
        end
    end
end

--TODO 特殊处理了八卦阵，含有八卦阵数据的怪物类型, 脚下显示八卦阵
function M:specialWuZhuang(gridUnit, gve_massifData, groupTrans, showGroundList )
    if not gridUnit.m_wuzhuangSign then
        return
    end
    local wuZhuangData = nil
    local wuZhuangId = nil
    for id, itemData in pairs(gve_massifData) do
        if itemData.type == GlobalConfig.GridType.Wuzhuang then
            wuZhuangData = itemData
            wuZhuangId = id
            break
        end
    end
    if not wuZhuangData then
        return
    end

    if gridUnit.specialId == wuZhuangId then
        return
    end
    if self.showWuzhuangList[gridUnit.m_gridId] then
        return
    end
    self:createObj(wuZhuangData, groupTrans, gridUnit, showGroundList )
end

