function M:createObj(xlsxData, parentTrans, gridUnit, showGroundList)
    local objectName = xlsxData.building_model
    local obj = nil
    local pos = gridUnit.position
    local gridId = gridUnit.m_gridId
    if xlsxData.boss_is and (xlsxData.boss_is > 0) and (not showGroundList[gridId]) then
        --- 进地图只创建一次boss
        local playerData = { id = xlsxData.boss_is, evo = 0 }
        local player_model = self.plyMgr:createPlayer(playerData,1,0,nil,nil)
        showGroundList[gridId] = {}
        player_model.loadPlayerViewFinish = function(ply)
            local obj = ply.obj
            if not IsNull(obj) then
                local scaleValue = xlsxData.boss_sca
                if scaleValue then
                    player_model:setScale(GlobalTools:CommonToFix(scaleValue))
                end
                local rotData = xlsxData.boss_rot
                if rotData then
                    local rotX = rotData[1] or 0
                    local rotY = rotData[2] or 0
                    local rotZ = rotData[3] or 0
                    ply.luaViewHelper.isSetRotation = false;
                    ply.tran.transform.rotation = Quaternion.Euler(rotX,rotY,rotZ)
                end
                --矫正boss偏移
                local bodyTrans = obj.transform:Find("body")
                local moveConfig = xlsxData.boss_move
                if (not IsNull(bodyTrans)) and moveConfig then
                    local posX = moveConfig[1] or 0
                    local posY = moveConfig[2] or 0
                    local posZ = moveConfig[3] or 0
                    local tempPos = bodyTrans.localPosition
                    self.bossPosList = {tempPos.x, tempPos.y, tempPos.z}
                    bodyTrans.localPosition = Vector3(posX, posY, posZ)
                end
                local fix_pos = FixVector3.New(0,0,0);
                fix_pos.x = GlobalTools:CommonToFix( pos.x );
                fix_pos.y = GlobalTools:CommonToFix( pos.y );
                fix_pos.z = GlobalTools:CommonToFix( pos.z );
                player_model:setPos( fix_pos, true )
                if showGroundList and showGroundList[gridId] then
                    showGroundList[gridId].obj = obj
                end
                
                -- 隐藏Boss阴影
                local shadow = ply.tranformHelper:FindObj(ply.tran, "shadow")
                if IsNull(shadow) == false then
                    shadow:SetActive(false)
                end
            end
        end
        showGroundList[gridId].gridId = gridId
        showGroundList[gridId].player_model = player_model
    else
        obj = ResourceUtil:GetUIItem("QiMenDunJia/sceneObject/"..objectName, parentTrans.gameObject, "ui_prefabs")
        if not IsNull(obj) then
            obj.transform.localPosition = pos
            showGroundList[gridId] = {
                obj = obj,
                gridId = gridId,
            }
            -- 王昊不让宝箱跳了
            --if gridUnit.m_gridType == GlobalConfig.GridType.GiftBag then
            --    local anim = obj:GetComponent("Animator")
            --    if (not IsNull(anim)) then
            --        anim:PlayInFixedTime(GiftBagAnimName.Idle)
            --    end
            --end
        end
    end
    if gridUnit.m_gridType == GlobalConfig.GridType.GiftBag then
        self:createGiftBagBarInfo(gridId)
    end
end

