-- 刷新UI玩家角色头像(返回当前位置)状态
function M:refreshPlayerImg()
    if not self.camera3D then
        return
    end
    if not self.player_view then
        return
    end
    local playerObj = self.player_view.obj
    if not IsNull(playerObj) then
        -- 视口坐标
        local viewCoord = self.camera3D:WorldToViewportPoint(playerObj.transform.position)
        if (viewCoord.x > 0 and viewCoord.x < 1 and viewCoord.y > 0 and viewCoord.y < 1 and viewCoord.z > self.camera3D.nearClipPlane and viewCoord.z < self.camera3D.farClipPlane) then
            self.isShowViewMainPlayerIcon = false
            self:sendEvent("show_playerImg_messag", {isShow = self.isShowViewMainPlayerIcon}, "QiMenDunJia.QiMenDunJiaMain");
            return
        end
        -- 屏幕外
        self.isShowViewMainPlayerIcon = true
        self:sendEvent("show_playerImg_messag", {isShow = self.isShowViewMainPlayerIcon}, "QiMenDunJia.QiMenDunJiaMain");
    end
end

-- 移动相机的格子刷新
function M:raycastEvent()
    local screenPos = Vector3(U3DUtil:Screen_Width() * 0.5, U3DUtil:Screen_Height() * 0.5, 0)
    local ray = self.camera3D:ScreenPointToRay(screenPos)
    local hitinfos = CS.UnityEngine.Physics.RaycastAll(ray);
    local count = hitinfos.Length
    if count > 0 then
        for i = 0, count - 1, 1 do
            local hitInfo = hitinfos[i]
            if hitInfo.collider.gameObject ~= null then
                local obj = hitInfo.collider.gameObject
                local objName = obj.name
                if objName == "scenePlane" then
                    -- 打到地图plane上
                    local collider = obj:GetComponent("BoxCollider")
                    if collider then
                        local targetPos = hitInfo.point
                        local curX = math.abs(targetPos.x)
                        local curZ = math.abs(targetPos.z)
                        local curWidth = math.floor(curX / Battle.SceneGridConfig.qmdj_grid_width)
                        local curHeight = math.floor(curZ / Battle.SceneGridConfig.qmdj_grid_height)
                        local curGridId = self.gridMgr:getGridIDByWidthAndHeight(curWidth, curHeight)
                        -- 有这个格子再刷新
                        --Logger.logError("摄像机打到Plane上========="..curGridId)
                        self.gridMgr:refreshGridInfo(true, curGridId, true)
                    end
                else
                    -- 打到已出现的格子上
                    local strTab = string.split( objName,'_')
                    if strTab[1] == "grid" then
                        local gridType = tonumber(strTab[2])
                        local gridWidth = tonumber(strTab[3])
                        local gridHeight = tonumber(strTab[4])
                        if (not gridWidth) or (not gridHeight)  then
                            return
                        end
                        local curGridId = self.gridMgr:getGridIDByWidthAndHeight(gridWidth, gridHeight)
                        if curGridId ~= self.gridMgr.lookGridId then
                            --Logger.logError("摄像机打到已出现的格子上========="..curGridId)
                            self.gridMgr:refreshGridInfo(true, curGridId, true)
                        end
                    end
                end
            end
        end 
    end
end

function M:UnityUpdate(dt)
    if self.isExteriorOpen then
        return
    end
    self.mouseDown = SceneManager:getCurSceneView().cameraController.mouseDown;
    if self.mouseDown == true then
        self:cameraRefresh(dt)
        self.mouseDownTime = self.mouseDownTime + dt;
    else
        self.mouseDownTime = 0;
    end
    
    if static_rootControl:can3DTouchByViewName("QiMenDunJia.QiMenDunJiaMain") then
        if SceneManager:getCurSceneView().cameraController.CanDrag == false then
            SceneManager:getCurSceneView().cameraController.CanDrag = (not self.isMove);
            SceneManager:getCurSceneView().cameraController.mouseDown = false;
        end
    else
        if SceneManager:getCurSceneView().cameraController.CanDrag == true then
            SceneManager:getCurSceneView().cameraController.CanDrag = false;
        end
    end

    if self.click_set_effect_time > 0 then
        self.click_set_effect_time = self.click_set_effect_time - dt;
        if self.click_set_effect_time <= 0 then
            if self.click_effect ~= nil then
                self.click_effect.transform.position = Vector3(100000,100000,100000);
            end
            self.click_set_effect_time = 0;
        end
    end
    
    ----更新玩家移动
    self:updatePlayerMove( dt )
    
    --发送到服务器
    if self.sendToServerNow == false then
        if self.autoUnlockSendServerTime > 0 then
            self.autoUnlockSendServerTime = self.autoUnlockSendServerTime - dt;
            if self.autoUnlockSendServerTime <= 0 then
                self.sendToServerNow = true;
            end
        end
    end

    --点击时间
    if self.curClickTime > 0 then
        self.curClickTime = self.curClickTime - dt;
        if self.curClickTime <= 0 then
            self.curClickTime = 0;
        end
    end

    if self.passivityCameraMovePos then
        self:passivityCameraMove(dt)
    end
end


--找路径   
-- 目标格子宽，高，是否不走到目标格子
function M:findPaths( target_w, target_h )
    --每次找路径都要清空重新找
    self.path:clear();
    --目标格子
    self.targetGrid = self.aStar.sceneData.data[target_w][target_h]
    if self.targetGrid ~= nil and self.startGrid ~= nil then
        -- AStar找到的路径
        self.path = self.aStar:findPath(self.startGrid,self.targetGrid)
        --for i = 1, self.path.Count do
        --    local grid = self.path:get(i-1)
            --Logger.logError(" AStar 寻路路径格子 ~~~ "..grid.index_pos.x.." -- "..grid.index_pos.y)
        --end
    end
    if self.path.Count <= 0 then
        self:noWalkGridHint(self.targetGrid.m_gridId)
        self:resetClickRoom();
        self.isTranfering = false;
    else
        self.notWalkList = {}
    end
end

-- 不可行格子提示
function M:noWalkGridHint(targetGrid)
    local tempGridUnit = self.gridMgr:getGridUnitById(targetGrid)
    --local gridId = targetGridUnit.m_gridId
    if self.gridMgr:isGridWalk(targetGrid) then
        local minGridId = self:getRoundWalkGridId(tempGridUnit)
        if minGridId > 0 then
            self.notWalkList[minGridId] = minGridId
            self:resetClickRoom()
            local minGridUnit = self.gridMgr:getGridUnitById(minGridId)
            self:ClickObjEvent(minGridUnit.w_pos, minGridUnit.h_pos, "gridGroup", nil)
        end
    else
        local isDependency = (tempGridUnit.m_gridType == GlobalConfig.GridType.Dependency)
        local targetGridUnit = isDependency and self.gridMgr:getGridUnitById(tempGridUnit.m_relationGridId) or tempGridUnit
        if targetGridUnit.specialId <= 0 then
            return
        end
        local gve_massifData = ConfigManager:getCfgByName("gve_massif")
        local groundData = gve_massifData[targetGridUnit.specialId]
        if not groundData then
            return
        end
        if (not groundData.building_slogn) or (groundData.building_slogn == "") then
            return
        end
        self:sendEvent("show_no_move_messag", {hintText = groundData.building_slogn}, "QiMenDunJia.QiMenDunJiaMain");
    end
end

-- 计算附庸格子周围最近的可行走格子
function M:getRoundWalkGridId(targetGridUnit)
    if targetGridUnit.m_relationGridId < 0 then
        return -1
    end
    -- 排除所有关联格子
    local parentGridUnit = self.gridMgr:getGridUnitById(targetGridUnit.m_relationGridId)
    local relevanceGridIds = parentGridUnit.m_relationGridIdList
    -- 子母格判断位置，移动到最近位置
    local allRoundGrids = {}
    -- 最佳距离格子,  
    local minGridId, minDirW, minDirH = -1, -1, -1
    local playerGridUnit = self.gridMgr:getGridUnitById(self.playerGridId)
    for _, itemGridId in pairs(relevanceGridIds) do
        local itemGridUnit = self.gridMgr:getGridUnitById(itemGridId)
        local roundGridUnits,_ = self:getAroundGridUnit(itemGridUnit)
        local isExist = false
        for index = 1, table.nums(roundGridUnits) do
            local curItemGridUnit = roundGridUnits[index]
            local curItemGridId = curItemGridUnit.m_gridId
            -- 不在子母格， 不是空格子，走过的
            if (relevanceGridIds[curItemGridId] == nil) and (curItemGridUnit.m_gridType ~= GlobalConfig.GridType.Empty) and self.gridMgr:isGridWalk(curItemGridId) then
                isExist = true
                local curDirW = math.abs(itemGridUnit.w_pos - playerGridUnit.w_pos)
                local curDirH = math.abs(itemGridUnit.h_pos - playerGridUnit.h_pos)
                allRoundGrids[itemGridUnit.m_gridId] = {
                    curDirW = curDirW,
                    curDirH = curDirH,
                }
            end
        end
    end
    
    -- 计算距离
    if table.nums(allRoundGrids) > 0 then
        for gridId, itemData in pairs(allRoundGrids) do
            if (self.notWalkList[gridId] == nil) then
                local curGridDirW = itemData.curDirW
                local curGridDirH = itemData.curDirH
                if minDirW < 0 and minDirH < 0 then
                    minGridId, minDirW, minDirH = gridId, curGridDirW, curGridDirH
                else
                    if (minDirW >= itemData.curDirW) and (minDirH >= itemData.curDirH) then
                        minGridId, minDirW, minDirH = gridId, curGridDirW, curGridDirH
                    else
                        if (minDirW + minDirH) > (itemData.curDirW + itemData.curDirH) then
                            minGridId, minDirW, minDirH = gridId, curGridDirW, curGridDirH
                        end
                    end
                end
            end
        end
    end
    return minGridId
end

--重新设定点击处理
function M:resetClickRoom()
    self.isMoveToRoom = false;
end

--开始移动
function M:startGo()
    --打断发送服务器的时间
    self.curMoveEndTime = 0;
    local pathCount = self.path.Count
    if pathCount > 0 then
        self.isMove = true;
        local cameraController = SceneManager:getCurSceneView().cameraController
        if cameraController then
            cameraController.CanDrag = (not self.isMove)
        end
        -- >1, 防止点击附近地块，角色run一下抽搐
        if self.player.animator and pathCount > 1 then
            self.player.animator:changeState("run")
        end
    end
    local startGridUnit = self.path.list[0]
    if not startGridUnit then
        return
    end
    local targetGridUnit = self.path.list[pathCount - 1]
    if not targetGridUnit then
        return
    end
    self:setStartAndTargetPlayerInfo(startGridUnit.m_gridId, targetGridUnit.m_gridId)
    local click_grid = self.aStar.sceneData.data[targetGridUnit.w_pos][targetGridUnit.h_pos]
    if click_grid.data ~= nil then
        local eventId = self:getEventId(click_grid.data);
        SceneManager.eventMgr:addEvent(eventId, click_grid.data);
    end

    if (self.player ~= nil) and (self.player_view ~= nil) and (SceneManager:getCurSceneView().cameraController) then
        SceneManager:getCurSceneView().cameraController.Target = self.player_view.tran
    end
end

-- 设置起点 和 终点 格子上的联盟成员显隐
function M:setStartAndTargetPlayerInfo(startGridId, targetGridId)
    if startGridId ~= targetGridId then
        local startGridUnit = self.gridMgr:getGridUnitById(startGridId)
        local targetGridUnit = self.gridMgr:getGridUnitById(targetGridId)
        -- 如果格子上有人，隐藏. 老格子上的人，显示
        local startPlayerId = startGridUnit.m_existPlayerUid
        local targetPlayerId = targetGridUnit.m_existPlayerUid
        if startPlayerId > 0 then
            self:setOneMemberPlayerByGridId(startPlayerId, true)
            self:sendUIMemberPlayerName(startPlayerId, 4)
        end
        if targetPlayerId > 0 then
            self:setOneMemberPlayerByGridId(targetPlayerId, false)
            self:sendUIMemberPlayerName(targetPlayerId, 3)
        end
    end
end

--发送到服务器路径
function M:sendToServer(targetGridId)
    --如果现在可以发送到服务器
    if self.movePassPath.Count > 0 and targetGridId then
        local path_list = {}
        for i=1,self.movePassPath.Count do
            local grid = self.movePassPath:get(i-1);
            local grid_id = self.gridMgr:getGridIDByWidthAndHeight(grid.index_pos.x,grid.index_pos.y)
            path_list[i] = grid_id;
        end
        local path_data = { path = path_list, cell_id = targetGridId }
        local targetGridUnit = self.gridMgr:getGridUnitById(targetGridId)
        --Logger.logError(path_data," 送到服务器的goto参数 ")
        if table.nums(path_list) > 1 then
            self:sendEvent("qmdj_goto",path_data,"QiMenDunJia.QiMenDunJiaMain")
        else
            -- 在临近格子，
            if (targetGridUnit.m_gridType == GlobalConfig.GridType.Normal) or (targetGridUnit.m_gridType == GlobalConfig.GridType.GiftBag) then
                self:sendEvent("qmdj_goto",path_data,"QiMenDunJia.QiMenDunJiaMain")
            else
                self:clickGridEvent(targetGridId)
            end
        end
        self.movePassPath:clear();
    end
end

-- 移动完成(服务器下行)
function M:serverMoveEndEvent(response)
    self.serverMapData = response
    if self.gridMgr then
        self.gridMgr:refreshWalkGrids(response.passed)
    end
    self.playerGridId = self.serverMapData.cell_id
    local tempGridId = response.click_id
    self:clickGridEvent(tempGridId, response)
    if self.isShowViewMainPlayerIcon then
        self.isShowViewMainPlayerIcon = false
        self:sendEvent("show_playerImg_messag", {isShow = self.isShowViewMainPlayerIcon}, "QiMenDunJia.QiMenDunJiaMain");
    end
end

-- 点击到格子的处理
function M:clickGridEvent(tempGridId, response)
    --LikeOO.Map2DControl:cameraShake(2, 0.3)
    local moveTargetGridUnit = self.gridMgr:getGridUnitById(tempGridId)
    local isDependency = (moveTargetGridUnit.m_gridType == GlobalConfig.GridType.Dependency)
    local relationGridUnit = isDependency and self.gridMgr:getGridUnitById(moveTargetGridUnit.m_relationGridId) or moveTargetGridUnit
    --  判断目标格子类型，弹出相应信息，
    local gridType = relationGridUnit.m_gridType
    if gridType == GlobalConfig.GridType.Normal or gridType == GlobalConfig.GridType.BirthPoint then
        -- 普通格子, 或出生点
        --self:clickNormalGridEvent()
        
    elseif gridType == GlobalConfig.GridType.Monster then
        -- 怪物 走到周围
        self:clickMonsterEvent(moveTargetGridUnit, relationGridUnit, response)
    elseif gridType == GlobalConfig.GridType.GiftBag then
        -- 宝箱
        self:clickGiftBagGridEvent(relationGridUnit, response)
    elseif gridType == GlobalConfig.GridType.ForceStatue then
        -- 力量雕像
        self:clickForceStatueGridEvent(relationGridUnit)
    elseif gridType == GlobalConfig.GridType.SwordDesk then
        -- 铸剑台
        self:clickSwordDeskGridEvent(relationGridUnit)
    elseif gridType == GlobalConfig.GridType.League then
        -- 联盟
        self:clickLeagueGrudEvent(relationGridUnit)
    elseif gridType == GlobalConfig.GridType.Shop then
        -- 商店
        self:clickShopGridEvent(relationGridUnit)
    elseif gridType == GlobalConfig.GridType.Wuzhuang then
        -- 八卦阵
        self:clickWuzhuangGridEvent(relationGridUnit)
    elseif gridType == GlobalConfig.GridType.Pillar then
        -- 柱子
        self:clickPillerGridEvent(relationGridUnit)
    end
end

-- 激活柱子下行
function M:activatePillerEvent(cells, pillerGridId)
    -- 1.刷新数据, 调用刷新方法（对应柱子消失，八卦阵的模型消失）
    self:refreshGridsInfo(cells)
    -- 2.播放柱子消失特效    
    local obj = ResourceUtil:GetUIItem("QiMenDunJia/sceneObject/Qmdj_zhuzi_eft", self.tempGroupTrans.gameObject, "ui_prefabs")
    local tempGridUnit = self.gridMgr:getGridUnitById(pillerGridId)
    if not IsNull(obj) then
        local pos = tempGridUnit.position
        obj.transform.localPosition = pos
        TimeTools:delayTimeUnity(1,function()
            if not IsNull(obj) then
                U3DUtil:DestroyAndBundle(obj, nil, nil, 0)
            end
        end)        
    end
    -- 3.震动，摄像机移动
    self:cameraShakeEvent(tempGridUnit)
end

-- 3.震动，摄像机移动
function M:cameraShakeEvent(tempGridUnit)
    if tempGridUnit.m_monsterRefreshGridId <= 0 then
        return
    end
    if not IsNull(self.camera) then
        SceneManager:getCurSceneView().cameraController.Target = nil
        local cameraDoTween = self.camera:GetComponent("DOTweenAnimation")
        cameraDoTween:DORestart()
        TimeTools:delayTimeUnity(cameraDoTween.duration,function()
            self:sendEvent("show_no_move_messag", {hintText = Language:getTextByKey("qmdj_text_0004")}, "QiMenDunJia.QiMenDunJiaMain");
            self:setPassivityCameraTargetPos(tempGridUnit)
        end)
    end
end

