-- 点击到怪物格子
function M:clickMonsterEvent( moveTargetGridUnit, relationGridUnit,response)
    -- 刷新数据
    local gridId = moveTargetGridUnit.m_gridId
    if response then
        local serverCells = response.cells
        local itemServerCell = serverCells[tostring(gridId)]
        moveTargetGridUnit = self.gridMgr:refreshGridData(gridId, itemServerCell)
    end
    local isSameGrid = (moveTargetGridUnit.m_gridId == relationGridUnit.m_gridId)
    local curGridUnit = isSameGrid and moveTargetGridUnit or relationGridUnit
    if curGridUnit.m_gridType ~= GlobalConfig.GridType.Monster then
        self:sendEvent("notExist_monster_messag", nil, "QiMenDunJia.QiMenDunJiaMain");
        return
    end
    self:sendEvent("show_monster_messag", {gridId = curGridUnit.m_gridId}, "QiMenDunJia.QiMenDunJiaMain");
end

-- 点击到宝箱格子
function M:clickGiftBagGridEvent(moveTargetGridUnit, response)
    local gridId = moveTargetGridUnit.m_gridId
    -- 刷新数据
    if response then
        local serverCells = response.cells
        local itemServerCell = serverCells[tostring(gridId)]
        self.gridMgr:refreshGridData(gridId, itemServerCell)
    end

    -- 移除模型（播完动画移除）
    if (self.showGiftBagList[gridId]~= nil) and (not IsNull(self.showGiftBagList[gridId].obj)) then
        local obj = self.showGiftBagList[gridId].obj
        local anim = obj:GetComponent("Animator")
        if (not IsNull(anim)) then
            anim:PlayInFixedTime(GiftBagAnimName.Got)
        end
        -- 动画
        self:deleteGiftBagBarInfo(gridId)
        local itemData = self.showGiftBagList[gridId] or {}
        local tempObj = (not IsNull(itemData.obj)) and (itemData.obj) or nil
        TimeTools:delayTimeUnity(1.68,function()
            if not IsNull(tempObj) then
                U3DUtil:DestroyAndBundle(tempObj, nil, nil, 0)
            end
            if response.reward then
                local reward = response.reward
                RewardUtil:rewardTipsByData(reward)
            end
            self.showGiftBagList[gridId] = nil
        end)
    end
    self:findPaths(moveTargetGridUnit.w_pos,moveTargetGridUnit.h_pos);
    self:startGo();
end

