    end
end

--点到Collider
function M:ClickObjEvent( gridWidth, gridHeight, data, id )
    --Logger.logError("点击格子的时间================="..os.time())
    if data == "gridGroup" then
        -- 点到地块
        if not self.gridMgr then
            return
        end
        if (not gridWidth) or (not gridHeight) then
            return
        end

        --起始格子和选中格子是同一个
        if self.startGrid.w_pos == gridWidth and self.startGrid.h_pos == gridHeight then
            return;
        end

        --当前点击时间 > 0 
        if self.curClickTime > 0 then
            --Logger.logWarningAlways(self.curClickTime, "MiGongScene_Model self.curClickTime")
            return;
        end

        --鼠标点击时间 > 0.2
        if self.mouseDownTime > 0.2 then
            --Logger.logWarningAlways(self.mouseDownTime, "MiGongScene_Model self.mouseDownTime")
            return;
        end

        --如果是在移动中
        if self.isInMoving == true then
            --Logger.logWarningAlways(self.isInMoving, "MiGongScene_Model self.isInMoving")
            return;
        end

        --在移动到目标点的时候
        if self.isMoveToRoom == true then
            --Logger.logWarningAlways(" 正在移动到目标点的时候不能点击 " )
            return;
        end

        if self.isMove ~= false then
            return
        end

        --在传送中不能点击
        if self.isTranfering == true then  
            return;
        end

        -- 防止视野移动过程中人物点击地块移动
        if (not SceneManager:getCurSceneView().cameraController.CanDrag) then
            return
        end
        
        -- 点击新格子的时候，清除一遍路径残留，
        -- 人物走过去(注意领取宝箱之后的两步是客户端走过去的，服务器的当前位置已经是宝箱位置)， movePassPath需要清空，不然下次的movePassPath里包含这两步
        self.movePassPath:clear();

        --我站立的格子
        local center = { w_pos = self.startGrid.w_pos, h_pos = self.startGrid.h_pos }
        --鼠标选中的格子
        local around = { w_pos = gridWidth, h_pos = gridHeight }
        local targetGridId = self.gridMgr:getGridIDByWidthAndHeight(gridWidth, gridHeight)
        --当前的格子数据
        self.select_map_data = self.gridMgr:getGridUnitById(targetGridId)
        --当前选中的格子 
        self.select_grid = self.aStar.sceneData.data[gridWidth][gridHeight];
        self.select_obj = obj;
        self:moveToTargetGridEvent(gridWidth, gridHeight)
        self:playSoundByGridId(targetGridId)
    end
end

function M:playSoundByGridId(targetGridId)
    local moveTargetGridUnit = self.gridMgr:getGridUnitById(targetGridId)
    local relationGridUnit = isDependency and self.gridMgr:getGridUnitById(moveTargetGridUnit.m_relationGridId) or moveTargetGridUnit
    --  判断目标格子类型，弹出相应信息，
    local gridType = relationGridUnit.m_gridType
    if gridType == GlobalConfig.GridType.Normal then
        audio:SendEvtUI("UI_Square_Click")
    elseif gridType == GlobalConfig.GridType.Monster then
        local gve_massifData = ConfigManager:getCfgByName("gve_massif")
        if moveTargetGridUnit.specialId and gve_massifData[moveTargetGridUnit.specialId] and gve_massifData[moveTargetGridUnit.specialId].boss_is > 0 then
            audio:SendEvtUI("UI_DJZHu")
        else
            audio:SendEvtUI("UI_Square_Mon")
        end
    elseif gridType == GlobalConfig.GridType.GiftBag then
        audio:SendEvtUI("UI_Guild_Donate_Gold_2")
    elseif gridType == GlobalConfig.GridType.League then
        audio:SendEvtUI("UI_DJBHui")
    elseif gridType == GlobalConfig.GridType.Shop then
        audio:SendEvtUI("UI_Guild_Shop")
    elseif gridType == GlobalConfig.GridType.ForceStatue then
        audio:SendEvtUI("UI_Go")
    elseif gridType == GlobalConfig.GridType.SwordDesk then
        audio:SendEvtUI("UI_DJZJTai")
    end
end

-- 移动结束
function M:moveToTargetGridEvent(gridWidth, gridHeight)
    self.isMoveToRoom = true;
    local gridType = self.select_map_data.m_gridType
    if gridType == GlobalConfig.GridType.Normal or gridType == GlobalConfig.GridType.BirthPoint then
        --特效物体
        if self.click_effect ~= nil then
            self.click_effect.transform.position = Vector3(self.select_map_data.m_posX, 0.2, self.select_map_data.m_posZ);
            self.click_set_effect_time = self.click_config_timer;
        end
    end
    --目标格子
    self:findPaths(gridWidth,gridHeight);
    self:startGo();

    --Logger.logError("移动结束的时间================="..os.time())
    self.gotoFinish = function()
        self.autoUnlockSendServerTime = self.autoClickCellTime;
        if self.sendToServerNow == true then
            self:moveEndEvent(self.select_map_data.m_gridId)
            self.sendToServerNow = false
        end
    end
end

function M:sendToServerAll(targetGridId)
    --移动结束的最后一个格子, 上边有操作
    self:sendToServer(targetGridId);
end

--- 定时获取刷新格子ids(只刷新周围一定范围的)
function M:getRadiusGridsByUI()
    local tempGrids = {}
    if self.gridMgr then
        local grids = self.gridMgr:getCurRadiusGridIds(self.playerGridId)
        for gridId, _ in pairs(grids) do
            table.insert(tempGrids, gridId)
        end
    end
    return tempGrids
end

--- 定时获取刷新全部怪物格子ids
function M:getGridsByMonsterType()
    local tempGrids = {}
    if self.gridMgr then
        for _, itemUnit in pairs(self.gridMgr.gridUnitList) do
            if itemUnit.m_gridType == GlobalConfig.GridType.Monster then
                table.insert(tempGrids, itemUnit.m_gridId)
            end
        end
    end
    return tempGrids
end

-- 计时刷新格子数据
function M:refreshGridsInfo(cells)
    for strGridId, itemData in pairs(cells) do
        -- 修改数据
        self.gridMgr:refreshGridData(tonumber(strGridId), itemData) 
    end
    self.gridMgr:refreshGridInfo( false, self.gridMgr.lookGridId )
end

function M:initMap()
    local sceneParent = U3DUtil:GameObject_Find("Scene")
    local areaNode = sceneParent.transform:Find("Area")
    self.left_Top = areaNode.transform:Find("Left_Top")
    self.right_Bottom = areaNode.transform:Find("Right_Bottom")
    self.sceneObj = ResourceUtil:GetUIItem("QiMenDunJia/sceneObject/"..self.qmdj_sceneName, sceneParent, "ui_prefabs")
    if (not IsNull(self.sceneObj)) then
        self.sceneObj.transform.localPosition = Vector3.zero
        local map_left_top = self.sceneObj.transform:Find("map_left_top")
        local map_right_bottom = self.sceneObj.transform:Find("map_right_bottom")
        if (not IsNull(self.left_Top)) and (not IsNull(self.right_Bottom)) and (not IsNull(map_left_top)) and (not IsNull(map_right_bottom)) then
            self.left_Top.localPosition = map_left_top.localPosition
            self.right_Bottom.localPosition = map_right_bottom.localPosition
        end
    end
end

--格子是否在周围
function M:isAround( center, around )
    local w_pos = around.w_pos - center.w_pos;
    local h_pos = around.h_pos - center.h_pos;
    if center.w_pos % 2 == 1 then
        if (w_pos == -1 and h_pos == 1)
                or (w_pos == 0 and h_pos == 1)
                or (w_pos == 1 and h_pos == 1)
                or (w_pos == 1 and h_pos == 0)
                or (w_pos == 0 and h_pos == -1)
                or (w_pos == -1 and h_pos == 0) then
            return true;
        end
    else
        if (w_pos == -1 and h_pos == 0)
                or (w_pos == 0 and h_pos == 1)
                or (w_pos == 1 and h_pos == 0)
                or (w_pos == 1 and h_pos == -1)
                or (w_pos == 0 and h_pos == -1)
                or (w_pos == -1 and h_pos == -1) then
            return true;
        end
    end
end

return M